-- 057: tier em 7 faixas, no padrão do ArcadeStat (Topo, Alto, Médio-Alto, Médio, Médio-Baixo, Baixo, Fundo),
-- mais Unique (gimmick ou muito fora da curva) e Sem classificação. A faixa importada vira a base do tier de cada chart;
-- o tier do clube (admin) e os votos da comunidade continuam por cima, agora na escala de -3 (Fundo) a +3 (Topo).
create table if not exists public.chart_tier_ref (
  chart_id   bigint primary key references public.charts (id) on delete cascade,
  band       smallint not null check (band between -3 and 3 or band in (8, 9)),  -- 3 topo … -3 fundo · 9 unique · 8 sem classificação
  source     text not null default 'arcadestat',
  updated_at timestamptz not null default now()
);
alter table public.chart_tier_ref enable row level security;
revoke all on public.chart_tier_ref from anon, authenticated;

