select c.id, case x.code when '7' then 3 when '6' then 2 when '5' then 1 when '4' then 0 when '3' then -1 when '2' then -2 when '1' then -3
                         when 'u' then 9 else 8 end
  from parsed x join public.charts c on c.version = 'phoenix2' and c.mode = x.mode and c.level = x.level and c.song_id = x.song
on conflict (chart_id) do update set band = excluded.band, source = 'arcadestat', updated_at = now();

-- escala nova: -3..3 (antes -2..2). Topo continua topo e Muito fácil vira Fundo.
do $$ declare r record; begin
  for r in select conrelid::regclass as t, conname from pg_constraint
            where contype = 'c' and conrelid in ('public.chart_reviews'::regclass, 'public.chart_tier_overrides'::regclass, 'public.tier_proposals'::regclass)
              and pg_get_constraintdef(oid) ~ 'tier' and pg_get_constraintdef(oid) ~ '-2'
  loop execute format('alter table %s drop constraint %I', r.t, r.conname); end loop;
end $$;
update public.chart_reviews set tier = case tier when 2 then 3 when 1 then 2 when -1 then -2 when -2 then -3 else tier end where tier is not null;
update public.chart_tier_overrides set tier = case tier when 2 then 3 when 1 then 2 when -1 then -2 when -2 then -3 else tier end;
update public.tier_proposals set to_tier = case to_tier when 2 then 3 when 1 then 2 when -1 then -2 when -2 then -3 else to_tier end,
                                 from_tier = case from_tier when 2 then 3 when 1 then 2 when -1 then -2 when -2 then -3 else from_tier end;
alter table public.chart_reviews add constraint chart_reviews_tier_7 check (tier between -3 and 3);
alter table public.chart_tier_overrides add constraint chart_tier_overrides_tier_7 check (tier between -3 and 3);
alter table public.tier_proposals add constraint tier_proposals_from_7 check (from_tier between -3 and 3);
alter table public.tier_proposals add constraint tier_proposals_to_7 check (to_tier between -3 and 3);

create or replace function public.propose_tier(p_chart bigint, p_to smallint, p_from smallint, p_reason text)
returns bigint language plpgsql security definer set search_path = public as $$
declare me uuid := auth.uid(); v_id bigint; v_hours int := coalesce((app_config()->'community'->>'tier_vote_hours')::int, 48); v_info jsonb;
begin
  if me is null then raise exception 'faça login primeiro' using errcode = '28000'; end if;
  perform close_due_tier_proposals();
  if not has_cleared(me, p_chart) then raise exception 'Só quem passou o chart pode propor mudança de tier.'; end if;
  if p_to is null or p_to not between -3 and 3 then raise exception 'tier inválido'; end if;
  if p_from is not null and p_from = p_to then raise exception 'Escolha um tier diferente do atual.'; end if;
  if exists (select 1 from tier_proposals where chart_id = p_chart and status = 'open') then
    raise exception 'Já existe uma votação aberta para este chart.';
  end if;
  if (select count(*) from tier_proposals where proposer = me and created_at > now() - interval '1 day') >= 10 then
    raise exception 'Limite de 10 propostas por dia.';
  end if;
  insert into tier_proposals (chart_id, proposer, from_tier, to_tier, reason, closes_at, yes)
  values (p_chart, me, p_from, p_to, nullif(trim(p_reason), ''), now() + make_interval(hours => greatest(1, least(v_hours, 336))), 1)
  returning id into v_id;
  insert into tier_votes (proposal_id, user_id, agree) values (v_id, me, true);
  select jsonb_build_object('song', s.id, 'title', s.title, 'mode', c.mode, 'level', c.level, 'to', p_to)
    into v_info from charts c join songs s on s.id = c.song_id where c.id = p_chart;
  perform notify(r.user_id, 'tier_vote_open', me, v_id::text, v_info) from chart_reviews r where r.chart_id = p_chart and r.user_id <> me;
  return v_id;
end $$;
revoke all on function public.propose_tier(bigint, smallint, smallint, text) from public, anon;
grant execute on function public.propose_tier(bigint, smallint, smallint, text) to authenticated;

-- faixa de referência de cada chart, para o app: [[chart, faixa], ...]
create or replace function public.chart_ref_tiers(p_version text default 'phoenix2')
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_array(r.chart_id, r.band)), '[]'::jsonb)
    from chart_tier_ref r join charts c on c.id = r.chart_id and c.version = p_version
$$;
revoke all on function public.chart_ref_tiers(text) from public;
grant execute on function public.chart_ref_tiers(text) to anon, authenticated;
